  const scope = {
    projectId: fixture.project.id,
    environmentId: options.environmentId ?? fixture.development.id,
    name: "Scoped fixture identity",
    ...(options.expiresAt ? { expiresAt: options.expiresAt } : {}),
  };
  const input: CreateServiceIdentityInput =
    purpose === "runtime"
      ? { ...scope, purpose }
      : { ...scope, purpose, workerId: options.workerId ?? "authorized-worker" };
