  if (options.activate !== false) {
    const staged = await currentSlot(fixture, slot.id);
    const activated = await fixture.broker.activate(
      fixture.freshOwner(),
      slot.id,
      fixture.transition.adapter.id,
      staged.revision,
      randomUUID(),
    );
    if (activated.state !== "succeeded")
      throw new Error("Access activation fixture did not complete");
  }
  return { identity: issued, slot: await currentSlot(fixture, slot.id), proof, value };
